#### aria_ratings

```sql
CREATE TABLE aria_ratings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    question TEXT NOT NULL,
    answer TEXT NOT NULL,
    chat_context JSONB,
    rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comments TEXT,
    username VARCHAR(255) DEFAULT 'unknown',
    user_email VARCHAR(255),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_aria_ratings_username ON aria_ratings(username);
CREATE INDEX idx_aria_ratings_user_email ON aria_ratings(user_email);
CREATE INDEX idx_aria_ratings_rating ON aria_ratings(rating);
CREATE INDEX idx_aria_ratings_created_at ON aria_ratings(created_at);
```

