### Frontend Integration - ARIA Search

```typescript
// Submit rating after user provides feedback
async function submitAriaRating(
  question: string,
  answer: string,
  chatHistory: Message[],
  rating: number,
  comments?: string
) {
  const response = await fetch(
    "https://ea-reference.shared.dev.pgwcloud.net/api/rating/v1/aria",
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        question,
        answer,
        chat_context: chatHistory,
        rating,
        comments: comments || "",
        username: getCurrentUser() || "unknown",
        user_email: getCurrentUserEmail() || null,
      }),
    }
  );

  return response.json();
}

// Update an existing ARIA rating
async function updateAriaRating(
  ratingId: string,
  rating?: number,
  comments?: string
) {
  const response = await fetch(
    `https://ea-reference.shared.dev.pgwcloud.net/api/rating/v1/aria/${ratingId}`,
    {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        rating,
        comments,
        username: getCurrentUser() || "unknown",
        user_email: getCurrentUserEmail() || null,
      }),
    }
  );

  if (response.status === 403) {
    throw new Error("You can only update your own ratings");
  }

  return response.json();
}

// Delete an ARIA rating
async function deleteAriaRating(ratingId: string) {
  const username = getCurrentUser() || "unknown";
  const userEmail = getCurrentUserEmail();

  const params = new URLSearchParams({ username });
  if (userEmail) {
    params.append("user_email", userEmail);
  }

  const response = await fetch(
    `https://ea-reference.shared.dev.pgwcloud.net/api/rating/v1/aria/${ratingId}?${params}`,
    {
      method: "DELETE",
    }
  );

  if (response.status === 403) {
    throw new Error("You can only delete your own ratings");
  }

  return response.status === 204;
}
```

