### Analytics Dashboard Integration

```typescript
// Fetch statistics for dashboard
async function fetchRatingStats() {
  const response = await fetch(
    "https://ea-reference.shared.dev.pgwcloud.net/api/rating/v1/stats"
  );
  return response.json();
}

// Fetch trends for charts
async function fetchRatingTrends(service: "aria" | "governance") {
  const response = await fetch(
    `https://ea-reference.shared.dev.pgwcloud.net/api/rating/v1/trends?service=${service}&period=30d`
  );
  return response.json();
}
```
